∀ (p : PureSFormal.CTS.Program) (w : UniformS.Word) (n : Nat),
  have t := UniformS.Certified.orbit n (UniformS.Board.tree (UniformS.Bridge.compile p) (UniformS.seed w));
  UniformS.Certified.halt t = true → UniformS.Archive.Complete p (PureSFormal.CTS.initial p w) (UniformS.Archive.bits t)
